// DO NOT ALTER CODE WRITTEN BELOW THIS LINE

function printToScreen(text) {

  const svg = d3.select("body")
    .append("svg")
    .attr("width", 1500)
    .attr("height", 100);

  svg.append("text")
    .attr("x", 100)
    .attr("y", 50)
    .attr("width", 450)
    .attr("height", 100);

  switch (typeof text) {
    case ("string"):
      svg.selectAll('text')
        .attr("x", -1000)
        .attr("font-weight", "bold")
        .attr("font-size", "30px")
        .attr("fill", "red")
        .attr("font-family", "Comic Sans")
        .attr("font-style", "italic")
        .text(text + " is a string!")
        .transition()
        .duration(1000)
        .attr("x", 100);
      break;
    case ("number"):
      svg.selectAll('text')
        .attr("x", 3000)
        .attr("font-size", "30px")
        .attr("fill", "peru")
        .attr("font-family", "Lato")
        .text(text + " is a number!")
        .transition()
        .duration(1000)
        .attr("x", 100);
      break;
    case ("boolean"):
      svg.selectAll('text')
        .attr("opacity", 0)
        .attr("font-size", "30px")
        .attr("font-family", "Gotu")
        .text(text + " is a boolean!")
        .attr("fill", "green")
        .transition()
        .duration(1000)
        .attr("opacity", 1);
      break;
    case ("object"):
      svg.selectAll('text')
        .text("null is an object!")
        .attr("font-family", "Tangerine")
        .attr("font-size", "48px")
        .attr("fill", "purple")
        .attr("transform", "translate(300,300)")
        .transition()
        .duration(1000)
        .attr("transform", "translate(0,0)")
      break;
    case ("undefined"):
      svg.selectAll('text')
        .text("undefined is not an object!")
        .attr("font-size", "72px")
        .attr("font-family", "Bigshot One")
        .attr("fill", "orange")
        .transition()
        .duration(1000)
        .attr("font-size", "30px")
      break;
    default:
      svg.selectAll('text')
        .attr("fill", "red")
        .text("Something went wrong, error! Error!");
  }

}

